renderWorkspace(status){if(this.state.screen!=='hub')return this.renderSubscreen();return({home:()=>this.renderHome(status),judgement:()=>this.renderObservedPage(),live:()=>this.renderLive(),store:()=>this.renderStore(),records:()=>this.renderRecords(),data:()=>this.renderData()})[this.state.workspace]?.()||this.renderHome(status)}
renderHome(status){const s=this.state.summary||{},latest=this.recentAnalyses[0],todayAnalysis=(analysisJob.status==='completed'&&localDay(analysisJob.completedAt)===localDay())||(latest&&localDay(latest.createdAt)===localDay()),next=nextHomeAction({...s,storeCount:this.state.stores.length||s.storeCount,draft:!!this.state.recordEditor,job:analysisJob,todayAnalysis}),records=this.bridge()?.getRecentRecords?.(2)||[];const action=s.activePlay&&next.action===s.activePlay.action?'resume-play':next.action;return `<section class="workspace home-workspace"><div class="kicker">TODAY</div><h1>今日のJUGEST</h1><section class="panel next-card"><div class="section-label">次にやること</div><h2>${esc(next.title)}</h2><p>${esc(next.meta)}</p><button type="button" class="primary-cta" data-action="${esc(action)}">${next.action==='analysis-return'?'解析を開く':next.action==='register-store'?'店舗を登録':'続ける'} <span aria-hidden="true">→</span></button></section><div class="section-label">最近の解析</div><div class="home-recent">${this.recentAnalyses.map(x=>`<button type="button" data-action="recent-analysis:${esc(x.id)}"><span><b>${esc(x.shop)}</b><small>${esc(localDay(x.createdAt))} · ${x.source?.days||0}日分の解析</small></span><span aria-hidden="true">›</span></button>`).join('')||'<div class="empty-card">解析結果はここから振り返れます。</div>'}</div><div class="section-label">最近の実戦</div><div class="home-recent">${records.map(x=>`<button type="button" data-action="recent-record:${esc(x.id)}"><span><b>${esc(x.shopName||'店舗未選択')} · ${esc(x.machineName)}</b><small>${esc(x.date)} · ${formatCount(x.playedG,'G')}</small></span><span aria-hidden="true">›</span></button>`).join('')||'<div class="empty-card">保存した実戦記録がここに並びます。</div>'}</div><section class="home-data"><b>データ状況</b><span>自動取得 ${s.linked&&s.enabledTargets?'ON':'OFF'}</span><span>最終同期 ${esc(s.syncLabel||'未同期')}</span><span>蓄積 ${formatCount(s.externalDayCount,'日')}</span><button type="button" data-workspace="data">詳細を見る</button></section></section>`}

