nceScreen();if(this.state.workspace==='data'&&this.state.screen==='collector')return this.renderCollectorScreen();if(this.state.workspace==='data'&&this.state.screen==='stores')return this.renderStoreManagementScreen();if(this.state.workspace==='data'&&this.state.screen==='import')return this.renderJsonImportScreen();if(this.state.workspace==='data'&&this.state.screen==='sync')return this.renderSyncScreen();if(this.state.workspace==='data'&&this.state.screen==='backup')return this.renderBackupScreen();const titles={rev:'後ヅモ',move:'移動比較',compare:'台比較',plan:'今日の作戦',analysis:'店舗解析',replay:'リプレイ',model:'モデル性能',log:'稼働記録',calendar:'カレンダー',strategy:'立ち回り分析',collector:'自動取得・取込',stores:'店舗管理',backup:'バックアップ'};const title=titles[this.state.screen]||workspaceLabel(this.state.workspace);return `<section class="workspace"><button class="back-row" type="button" data-workspace="${this.state.workspace}">‹ ${workspaceLabel(this.state.workspace)}</button><div class="kicker">${esc(this.state.workspace.toUpperCase())}</div><h1>${esc(title)}</h1><div class="error-panel">画面を読み込めなかったよ。ホームからもう一度開いてね。</div></section>`}

