hanaResultPanel(h,mode='live'){const r=mode==='rev'?h?.reverseResult:h?.liveResult;if(!r){return `<section class="panel hana-result"><div class="empty-card">データを入れるとここに判別結果が出るよ。</div></section>`}const q=r.q||[],m=h.config||{},metrics=r.metrics||null,warnings=r.warnings||[];return `<section class="panel hana-result"><div class="judge-result-top"><div><small>期待設定</small><strong data-hana-es>${metrics?fmtES(metrics.expectedSetting):'—'}</strong></div><div class="judge-pills"><span><small>設定4+</small><b data-hana-p4>${metrics?pct(metrics.p4):'—'}</b></span><span><small>${m.labels?.at(-1)==='V'?'設定V':'最上位'}</small><b data-hana-top>${metrics?pct(metrics.pTop):'—'}</b></span></div></div>${mode==='live'?liveCompactDistribution(q,'hana',!!metrics,m.labels):''}<div class="prob-strip hana-prob-strip">${(m.labels||[]).map((label,i)=>`<div><small>${esc(label)}</small><b data-hana-q="${i}">${q.length?pct(q[i]||0):'—'}</b></div>`).join('')}</div>${mode==='rev'?`<div class="hana-reverse-est"><span><small>推定ベル</small><b data-hana-bell>${r.reverse&&Number.isFinite(r.reverse.inferredDenom)?'1/'+r.reverse.inferredDenom.toFixed(2):'—'}</b></span><span><small>推定回数</small><b data-hana-bell-count>${r.reverse&&Number.isFinite(r.reverse.inferredBell)?Math.round(r.reverse.inferredBell)+'回':'—'}</b></span></div>`:''}<div class="judge-warning" data-hana-warning ${warnings.length?'':'hidden'}>${esc(warnings.join(' / '))}</div>${mode==='live'&&r.own?.factors?.length?`<details class="hana-factors"><summary>使用した判別要素</summary>${r.own.factors.map(f=>`<div class="${f.used?'':'off'}"><b>${esc(f.label)}</b><small>${esc(f.detail||'')}</small></div>`).join('')}</details>`:''}</section>`}
hanaCounter(label,path,value,scope='live'){return `<article class="metric-card"><div class="metric-head"><b>${esc(label)}</b></div><div class="metric-control"><button type="button" data-hana-count="${esc(path)}" data-hana-scope="${scope}" data-delta="-1">−</button><input type="number" min="0" inputmode="numeric" data-hana-field="${esc(path)}" data-hana-scope="${scope}" value="${esc(value??'')}" placeholder="0"><button type="button" data-hana-count="${esc(path)}" data-hana-scope="${scope}" data-delta="1">＋</button></div></article>`}

